add('matrix-nine','''$ {display:grid;grid-template-columns:var(--gap-lg) repeat(3,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr)) var(--gap-lg);gap:var(--gap-sm);padding:var(--gap-sm);} $ .cell{display:flex;flex-direction:column;justify-content:center;gap:var(--gap-sm);padding:var(--gap);background:var(--n-1);border-radius:var(--radius);} $ .cell.on{background:var(--a1);color:var(--a1-on);} $ .cell:nth-of-type(3){grid-column:2;grid-row:1;} $ .cell:nth-of-type(4){grid-column:3;grid-row:1;} $ .cell:nth-of-type(5){grid-column:4;grid-row:1;} $ .cell:nth-of-type(6){grid-column:2;grid-row:2;} $ .cell:nth-of-type(7){grid-column:3;grid-row:2;} $ .cell:nth-of-type(8){grid-column:4;grid-row:2;} $ .cell:nth-of-type(9){grid-column:2;grid-row:3;} $ .cell:nth-of-type(10){grid-column:3;grid-row:3;} $ .cell:nth-of-type(11){grid-column:4;grid-row:3;} $ .axis-x{grid-column:2 / -1;grid-row:4;display:flex;justify-content:space-around;font-size:var(--type-14);} $ .axis-y{grid-column:1;grid-row:1 / 4;display:flex;flex-direction:column-reverse;justify-content:space-around;font-size:var(--type-14);} $ .name{font-size:var(--type-20);} $ .note{font-size:var(--type-16);} @container(max-width:700px){$ .name{font-size:var(--type-16);} $ .note{font-size:var(--type-12);}}
''')
add('positioning','''$ {margin:var(--gap-lg);padding:var(--pad);background:linear-gradient(to right,var(--page) calc(50% - 1px),var(--n-4) 50%,var(--page) calc(50% + 1px)),linear-gradient(to bottom,var(--page) calc(50% - 1px),var(--n-4) 50%,var(--page) calc(50% + 1px));} $::after{content:'';position:absolute;left:0;right:0;top:50%;height:1px;background:var(--n-4);} $ .axis-x{position:absolute;left:0;right:0;bottom:calc(0px - var(--gap));display:flex;justify-content:space-between;font-size:var(--type-14);} $ .axis-y{position:absolute;left:0;top:0;bottom:0;display:flex;flex-direction:column-reverse;justify-content:space-between;font-size:var(--type-14);} $ .mark{position:absolute;left:calc(var(--x) * .8% + 10%);bottom:calc(var(--y) * .8% + 10%);border-radius:50%;background:var(--n-2);padding:var(--gap-sm);transform:translate(-50%,50%);z-index:1;} $ .mark.on{background:var(--a1);color:var(--a1-on);} $ .mark .name{font-size:var(--type-16);white-space:nowrap;} $ .seat.logo{width:64px;height:64px;border-radius:50%;} @container(max-width:600px){$ .mark .name{font-size:var(--type-12);}}
''')
add('network','''$ {padding:var(--pad);isolation:isolate;} $ .node{position:absolute;left:calc(var(--x) * .8% + 10%);top:calc(var(--y) * .8% + 10%);transform:translate(-50%,-50%);width:100px;height:100px;border-radius:50%;background:var(--a1-2-soft);border:var(--stroke) solid var(--a1);display:flex;align-items:center;justify-content:center;text-align:center;padding:var(--gap-sm);z-index:1;} $ .node.on{background:var(--a1);color:var(--a1-on);} $ .name{font-size:var(--type-18);} $ .link{position:absolute;left:calc(var(--x1) * .8% + 10%);top:calc(var(--y1) * .8% + 10%);width:calc(sqrt(pow(var(--x2) - var(--x1),2) + pow(var(--y2) - var(--y1),2)) * .8%);height:1px;background:var(--n-4);transform-origin:left center;transform:rotate(calc(atan2(var(--y2) - var(--y1),var(--x2) - var(--x1))));z-index:0;} $ .link.strong{height:2px;background:var(--a1);} @container(max-width:650px){$ .node{width:70px;height:70px;} $ .name{font-size:var(--type-14);}}
''')
add('code','''$ {display:flex;flex-direction:column;justify-content:center;gap:var(--gap);background:var(--n-1);border-radius:var(--radius);padding:var(--pad);} $>.name{font-size:var(--type-16);border-bottom:var(--stroke) solid var(--n-4);padding-bottom:var(--gap-sm);} $ .lines{font-family:var(--font-body);font-size:var(--type-18);line-height:var(--body-line);letter-spacing:var(--body-track);counter-reset:ln;} $ .lines p{white-space:pre-wrap;overflow-wrap:anywhere;counter-increment:ln;font-variant-numeric:tabular-nums;} $.numbered .lines p::before{content:counter(ln);display:inline-block;width:var(--gap-lg);color:var(--n-7);font-size:var(--type-14);} $ .k{color:var(--a1);font-weight:var(--name-weight);} $ .s{color:var(--good);} $ .c{color:var(--n-7);} $ .n{color:var(--a2);} @container(max-width:600px){$ .lines{font-size:var(--type-14);}}
''')
# Ensure every element has explicit reduction steps, even for small inline primitives.
for name in css:
 if '@container' not in css[name]: add(name,'@container(max-width:500px){$ .name{font-size:var(--type-18);} $ .note{font-size:var(--type-14);}}')
 (C/'elements'/name/'element.css').write_text(css[name])
print('Built',len(css),'element folders;',sum(1 for _ in C.rglob('fixtures/*.html')),'fixtures')
